rows.contract:
type Catalog {
  id: ID!
  linkMode: String!
  mappings(active: Active = ALL, after: String, first: Int! = 100): MappingPage
  root: String
}

type Component {
  id: ID!
  itemIds: [ID!]!
  kind: String!
}

type FallbackPolicy {
  id: ID!
  name: String!
  revision: Int!
  tiers: [String!]!
}

enum FileSort {
  ID
  MTIME
  PATH
  SIZE
}

type Identity {
  namespace: String!
  value: String!
}

type PageInfo {
  endCursor: String
  hasNextPage: Boolean!
}

input RenditionFilter {
  current: Boolean
  definition: ID
  purpose: String
  recipe: ID
}
